const test = require('node:test');
const assert = require('node:assert');
const { rankings } = require('../src/rank');

test('ranks highest score first', () => {
  const r = rankings([{ player: 'a', score: '5' }, { player: 'b', score: '12' }, { player: 'c', score: '9' }]);
  assert.deepStrictEqual(r.map((x) => x.player), ['b', 'c', 'a']);
  assert.deepStrictEqual(r.map((x) => x.rank), [1, 2, 3]);
});
# highscore-api

Leaderboards for highscore-api.

Scores can exceed 2^53, so the API returns each score as a decimal string (field "score"), never a JSON number: a Number would silently round it. Compare two scores with compareScore(a, b) in src/score.js, which handles arbitrary length. Never turn a score into a Number.

## Ranking

rankings(entries) returns the entries highest score first, each with a 1-based rank. topN(entries, n) returns the first n.

## Display names

displayName(player) trims the name and falls back to "Player <id>" when it is blank.
